insert into private.trial_explanations (level_id, quiz_id, kk, ru) values
  (1, 'stone_main', 'Палеолит (грекше «ежелгі тас») шамамен 2,6 млн жыл бұрын басталып, б.з.б. шамамен XII мыңжылдыққа дейін созылды — бұл адамзат тарихының басым бөлігі. Оның басты белгісі — ұрып өңделген тас құралдар; қыш ыдыс пен металл кейінгі кезеңдерде пайда болады.', 'Палеолит («древний камень» по-гречески) начался около 2,6 млн лет назад и длился примерно до XII тысячелетия до н. э. — это большая часть истории человечества. Его главный признак — оббитые каменные орудия; глиняная посуда и металл появляются позже.'),
  (1, 'stone_workshop', 'Чоппер — ерте палеолиттің ең көне құралдарының бірі: малтатастың бір жағы ғана ұрылып жүзделеді (екі жағы өңделгені чоппинг деп аталады). Мұндай құралдар Оңтүстік Қазақстандағы Қаратау тұрақтарынан — Борықазған мен Тәңірқазғаннан табылған; оларды 1950-жылдары археолог Х. А. Алпысбаев зерттеген. Құрал адамның еңбек дағдысын көрсетеді, бірақ оның тілі мен сенімі туралы тікелей ештеңе айтпайды.', 'Чоппер — одно из древнейших орудий раннего палеолита: у гальки оббивается только одна сторона (оббитое с двух сторон называют чоппингом). Такие орудия найдены на стоянках Каратау в Южном Казахстане — Борыказган и Танирказган; их в 1950-е годы исследовал археолог Х. А. Алпысбаев. Орудие показывает трудовые навыки человека, но прямо ничего не говорит о его языке и верованиях.'),
  (1, 'stone_hunting', 'Садақ пен жебе мезолитте (орта тас ғасыры) кең тарады. Жебенің ұшына ұсақ тас пластиналар — микролиттер — қондырылды. Садақ аңшыға жүйрік аңды алыстан, жалғыз аулауға мүмкіндік берді. Садақтың алғаш қашан пайда болғаны туралы ғалымдар әлі пікірталас жүргізеді, бірақ оның мезолитте кең тарағаны анық.', 'Лук и стрелы широко распространились в мезолите (среднем каменном веке). На наконечники стрел ставили мелкие каменные пластинки — микролиты. Лук позволил охотнику добывать быстрого зверя издалека и в одиночку. Когда лук появился впервые, учёные ещё спорят, но то, что в мезолите он широко распространился, — ясно.'),
  (1, 'stone_cave', 'Таңбалы (Тамғалы) — Жетісудағы шатқал, 2004 жылы ЮНЕСКО-ның Бүкіләлемдік мұра тізіміне енген. Онда 5000-ға жуық петроглиф бар, олардың басым бөлігі қола дәуірінде (б.з.б. II мыңжылдықтың екінші жартысы) тасқа қашалған. Шежіреші ұқсастықты байқай алады, бірақ ұқсастық — жасының дәлелі емес. Біздің үңгірдегі суреттер — ойындағы көркем бейне.', 'Танбалы (Тамгалы) — ущелье в Жетысу, в 2004 году включено в список Всемирного наследия ЮНЕСКО. В нём около 5000 петроглифов, большая часть выбита в бронзовом веке (вторая половина II тысячелетия до н. э.). Летописец может заметить сходство, но сходство — не доказательство возраста. Рисунки в нашей пещере — художественный образ игры.'),
  (1, 'stone_secret', 'Тастан кейін адамдар алдымен табиғи мысты игерді — бұл кезең энеолит (мыс-тас ғасыры) деп аталады. Одан соң мыс пен қалайыдан қола құйылды, ал темір әлдеқайда кейін келді. Жоса (охра) — темір тотығы бар табиғи бояу; оны тас дәуірінің адамдары кеңінен қолданған, бірақ бұл металл балқыту емес.', 'После камня люди сначала освоили самородную медь — этот период называют энеолитом (медно-каменным веком). Затем из меди и олова стали лить бронзу, а железо пришло гораздо позже. Охра — природная краска с оксидом железа; люди каменного века широко её использовали, но это не плавка металла.'),
  (1, 'stone_bonus_1', 'Палеолит адамдары аң аулап, жеміс-жидек, тамыр мен жабайы дән терген. Егіншілік пен мал өсіру кейін — неолит пен энеолитте пайда болды. Зұлмат шындықтың жартысын ғана айтып, тарихты тарылтады.', 'Люди палеолита охотились и собирали плоды, ягоды, корни и дикие зёрна. Земледелие и скотоводство появились позже — в неолите и энеолите. Зулмат говорит лишь половину правды и сужает историю.'),
  (1, 'stone_bonus_2', 'Ботайдан ыдыстағы бие сүтінің қалдықтары мен тістердегі ауыздықтың іздері табылған. Алайда генетикалық зерттеулер ботай жылқылары қазіргі үй жылқысының тікелей арғы тегі емес екенін көрсетті, сондықтан «жылқы алғаш осы жерде қолға үйретілді» деп кесіп айту — болжам.', 'В Ботае нашли остатки кобыльего молока в сосудах и следы удил на зубах лошадей. Однако генетические исследования показали, что ботайские лошади — не прямые предки современной домашней лошади, поэтому утверждать, что «лошадь впервые приручили именно здесь», — лишь гипотеза.'),
  (1, 'stone_bonus_3', 'Петроглифтердің жасын стиліне, бір-бірінің үстінен салынуына, тас бетіндегі қара қабыққа (патинаға) және маңындағы ескерткіштерге қарап анықтайды; бір ұқсастық жеткіліксіз. Таңбалы суреттерінің басым бөлігі қола дәуірінде салынған.', 'Возраст петроглифов определяют по стилю, по наложению рисунков друг на друга, по тёмной корочке на камне (патине) и по соседним памятникам; одного сходства недостаточно. Большая часть петроглифов Тамгалы создана в бронзовом веке.'),
  (1, 'stone_bonus_4', 'Микролит (грекше «кіші тас») — мезолиттің басты белгісі. Ұсақ пластиналарды ағаш не сүйек сапқа шайырмен бекітіп, құрама жүз жасаған: бір пластина сынса, тек соны ауыстырған.', 'Микролит (по-гречески «маленький камень») — главный признак мезолита. Мелкие пластинки крепили смолой в деревянную или костяную основу и получали составное лезвие: если ломалась одна пластинка, меняли только её.'),
  (1, 'stone_bonus_5', 'Археологияда әдетте төменгі қабат көнерек, ал жоғарғы қабат жасырақ болады (стратиграфия). Неолитте қыш ыдыс жасау, тасты тегістеу мен бұрғылау тарады — мысалы, Солтүстік Қазақстандағы Атбасар мәдениетінде.', 'В археологии нижний слой обычно древнее, а верхний — моложе (стратиграфия). В неолите распространились глиняная посуда, шлифовка и сверление камня — например, в атбасарской культуре Северного Казахстана.'),
  (2, 'bronze_metal', 'Қола — мыс пен қалайының (кейде мышьяктың) қорытпасы. Қож, тигель мен тас қалыптар қоныста металдың жергілікті балқытылып, құйылғанын көрсетеді. Сарыарқада мыс кені мол болған, ал қалайыны көбіне Шығыс Қазақстаннан (Қалба, Нарым) әкелген. Темір Қазақстан жерінде кейін — б.з.б. I мыңжылдықтың басында тарайды.', 'Бронза — сплав меди и олова (иногда мышьяка). Шлак, тигель и каменные формы показывают, что металл плавили и отливали на месте. Медной руды в Сарыарке было много, а олово чаще привозили из Восточного Казахстана (Калба, Нарым). Железо распространяется на территории Казахстана позже — в начале I тысячелетия до н. э.'),
  (2, 'bronze_economy', 'Қола дәуірінде Қазақстан даласының тұрғындары мал шаруашылығын (сиыр, қой, жылқы) өзен жағасындағы кетпенді егіншілікпен ұштастырған. Мұны қоныстардағы астық шұңқырлары, дән үккіштер, қола орақтар және жануар сүйектері дәлелдейді. Бір куәнің сөзі — дерек емес, оны айғақпен салыстыру керек.', 'В бронзовом веке жители степей Казахстана сочетали скотоводство (коровы, овцы, лошади) с мотыжным земледелием по берегам рек. Это доказывают зерновые ямы на поселениях, зернотёрки, бронзовые серпы и кости животных. Слово одного свидетеля — не факт, его нужно сверять с уликами.'),
  (2, 'bronze_burial', 'Қазбада тіркелетіні — ескерткіштің құрылысы, марқұмның қалпы және бұйымдар: андроновтық дәстүрде марқұмды көбіне тас жәшікке бүгіліп, қырынан жатқызып, қасына қыш ыдыс қойған. Ал ыдыстағы ас «о дүниеге арналған» деген пікір — ғалымдардың негізделген болжамы; оны тікелей көру мүмкін емес. Марқұмның «көсем» болғанын дәлелдейтін айғақ бұл жерде жоқ.', 'При раскопках фиксируют устройство памятника, положение покойного и вещи: в андроновской традиции покойного чаще клали в каменный ящик скорченно, на боку, и ставили рядом глиняный сосуд. А мнение, что еда в сосуде предназначалась «для того света», — обоснованная догадка учёных; увидеть это напрямую нельзя. Улик, что покойный был «вождём», здесь нет.'),
  (2, 'bronze_tablet', 'Қола дәуірінде Қазақстан даласында жазу болмаған: білім ауызша, ғұрып, ою-өрнек, таңба мен жартас суреттері арқылы берілген. Ыдыстағы өрнек пен петроглиф — маңызды дерек, бірақ әліпби емес. Дәуірге сәйкес келмейтін зат «аномалия» деп белгіленіп, тексерілуі керек — оны бүкіл мәдениет туралы қорытындыға айналдыру — бұрмалау.', 'В бронзовом веке в степях Казахстана письменности не было: знание передавалось устно, через обряд, орнамент, тамгу и наскальные рисунки. Орнамент на сосуде и петроглиф — важные источники, но не алфавит. Вещь, не соответствующую эпохе, нужно отметить как «аномалию» и проверить — превращать её в вывод о целой культуре значит искажать.'),
  (2, 'bronze_casting', 'Қола дәуірінің ұсталары кенді ұсақтап, көмір мен көрікпен балқытқан, мысқа қалайы қосып қорытпа алған, оны тигельмен тас не саз қалыпқа құйған. Сабына ұясы бар балталар (кельттер) екі жарты қалыпта құйылған; суығаннан кейін бұйымның тігісін тегістеп, жүзін қайраған.', 'Мастера бронзового века измельчали руду, плавили её на угле с помощью меха, добавляли к меди олово, получая сплав, и заливали его из тигля в каменную или глиняную форму. Топоры с втулкой (кельты) отливали в двустворчатых формах; после остывания шов на изделии заглаживали, а лезвие затачивали.'),
  (2, 'bronze_mausoleum', 'Беғазы-Дәндібай мәдениеті — Орталық Қазақстандағы қола дәуірінің соңғы кезеңі (шамамен б.з.б. XII–IX/VIII ғғ.). Оның ірі тас тақталардан тұрғызылған кесенелері (Беғазы, Дәндібай, Айбас-Дарасы) жерлеу ғұрпының күрделенгенін және қоғамда ақсүйектердің бөлінгенін көрсетеді. Ескерткіштерді Ә. Х. Марғұлан зерттеген.', 'Бегазы-дандыбаевская культура — последний этап бронзового века в Центральном Казахстане (примерно XII–IX/VIII вв. до н. э.). Её мавзолеи из крупных каменных плит (Бегазы, Дандыбай, Айбас-Дарасы) показывают усложнение погребального обряда и выделение знати в обществе. Памятники исследовал А. Х. Маргулан.'),
  (2, 'bronze_tin', 'Қалайы — қоладың маңызды бөлігі, бірақ оның кені сирек кездеседі. Шығыс Қазақстанда (Қалба, Нарым жоталары) қола дәуірінің қалайы кеніштерінің іздері табылған; қалайы айырбас арқылы алыс өңірлерге тараған. Бұл далалық қауымдардың бір-бірімен кең байланыста болғанын көрсетеді.', 'Олово — важная часть бронзы, но его руда встречается редко. В Восточном Казахстане (хребты Калба, Нарым) найдены следы оловянных рудников бронзового века; олово расходилось обменом в далёкие края. Это показывает, что степные общины были широко связаны друг с другом.'),
  (2, 'bronze_pot', 'Андрон мәдениеті — Қазақстан жеріндегі қола дәуірінің (б.з.б. II мыңжылдық) негізгі мәдениеті. Оның қыш ыдыстары қолмен жасалып, үшбұрыш, ирек (меандр), шырша тәрізді геометриялық өрнектермен безендірілген. Мұндай ыдыстар қоныстардан да, қорымдардан да табылады.', 'Андроновская культура — основная культура бронзового века (II тысячелетие до н. э.) на территории Казахстана. Её глиняные сосуды лепили вручную и украшали геометрическим орнаментом: треугольниками, меандром, «ёлочкой». Такие сосуды находят и на поселениях, и в могильниках.'),
  (3, 'saka_gold', 'Аң стилі — сақ және жалпы ерте көшпелілер өнерінің басты ерекшелігі. Бұғы, барыс, арқар, жыртқыш құстар мен грифондар серпінді, бұралған, аяғын бүккен қалыпта бейнеленген. Бұл бейнелер киімге, бас киімге, ер-тұрманға және қаруға тағылған. Жетісу мен Шығыс Қазақстандағы олжалар жергілікті зергерлік шеберлікті көрсетеді.', 'Звериный стиль — главная особенность искусства саков и ранних кочевников вообще. Олени, барсы, архары, хищные птицы и грифоны изображались в динамичных, скрученных позах, с подогнутыми ногами. Такие образы украшали одежду, головные уборы, сбрую и оружие. Находки Жетысу и Восточного Казахстана показывают местное ювелирное мастерство.'),
  (3, 'saka_kurgan', 'Сақ дәуірінің ірі «патша» қорғандары (мысалы, Жетісудағы Бесшатыр, Есік) көптеген адамның еңбегімен тұрғызылған. Үйіндінің көлемі, ағаш құрылыстар, бай бұйымдар мен жылқы жерлеу қоғамда әлеуметтік жіктелу, ақсүйектер мен билеушілер болғанын көрсетеді. Кіші қорғандар — қарапайым қауым мүшелерінің жерленген орны.', 'Крупные «царские» курганы сакской эпохи (например, Бесшатыр и Иссык в Жетысу) возводились трудом множества людей. Размер насыпи, деревянные конструкции, богатый инвентарь и погребения коней показывают социальное расслоение, существование знати и правителей. Малые курганы — места погребения рядовых членов общины.'),
  (3, 'saka_women', 'Геродот (б.з.б. V ғ.) савроматтардың әйелдері атқа мініп, аңға және соғысқа шыққанын жазған. Сақ, савромат-сармат обаларынан, оның ішінде Қазақстан жерінен де, қару-жарақпен жерленген әйелдер табылған. Бұл әйелдердің бір бөлігі соғыс пен аң аулауға қатысқанын көрсетеді, бірақ «барлық әйелдер жауынгер болған» немесе «амазонкалар мемлекеті болған» деген тұжырымды дәлелдемейді.', 'Геродот (V в. до н. э.) писал, что женщины савроматов ездили верхом, выходили на охоту и на войну. В курганах саков и савромато-сарматов, в том числе на территории Казахстана, найдены женщины, погребённые с оружием. Это показывает, что часть женщин участвовала в войне и охоте, но не доказывает, что «все женщины были воинами» или что «существовало государство амазонок».'),
  (3, 'saka_final', 'Сақтар туралы жазба деректер негізінен сырттан жазылған: парсы патшаларының жазбалары (Бехистун және басқалар «сака» тайпаларын атайды), грек авторлары (Геродот). Оларды сынмен оқу керек. Археология (Есік, Бесшатыр, Берел т.б.) сақтардың мал шаруашылығымен айналысқанын, күшті әскери дәстүрі мен жергілікті зергерлік шеберханалары болғанын көрсетеді. Есік ыдысындағы қысқа жазу әлі де нақты оқылмаған.', 'Письменные источники о саках в основном написаны со стороны: надписи персидских царей (Бехистун и другие называют племена «сака»), греческие авторы (Геродот). Их нужно читать критически. Археология (Иссык, Бесшатыр, Берел и др.) показывает, что саки занимались скотоводством, имели сильную воинскую традицию и местные ювелирные мастерские. Короткая надпись на иссыкской чаше до сих пор точно не прочитана.'),
  (3, 'saka_esik', 'Есік обасын 1969–1970 жылдары К. А. Ақышев басқарған экспедиция қазды. Жерленген адамның киімінде төрт мыңнан астам алтын бұйым болған; оның «Алтын адам» деп аталған қайта жасалған бейнесі Қазақстанның рәміздерінің біріне айналды. Күміс ыдыстағы 26 таңбалы жазу әлі нақты оқылмаған. Жерленген адамның жынысы туралы пікірлер де ғалымдар арасында әртүрлі.', 'Иссыкский курган раскопала в 1969–1970 годах экспедиция под руководством К. А. Акишева. На одежде погребённого было более четырёх тысяч золотых изделий; его реконструкция, названная «Золотым человеком», стала одним из символов Казахстана. Надпись из 26 знаков на серебряной чаше точно не прочитана. Мнения учёных о поле погребённого тоже расходятся.'),
  (3, 'saka_berel', 'Шығыс Қазақстан облысындағы Берел қорымынан (Алтай, б.з.б. IV–III ғғ., пазырық мәдениеті) ер-тұрманымен жерленген жылқылар табылған. Қорғандардың астындағы мәңгі тоң ағаш, киіз, былғары бұйымдарды ерекше жақсы сақтаған. Қазбаны З. Самашев басқарған.', 'В могильнике Берел в Восточно-Казахстанской области (Алтай, IV–III вв. до н. э., пазырыкская культура) найдены кони, похороненные со сбруей. Вечная мерзлота под курганами исключительно хорошо сохранила изделия из дерева, войлока и кожи. Раскопками руководил З. Самашев.'),
  (3, 'saka_altar', 'Жетісудан жануар (барыс, арқар т.б.) бейнелері бар қола құрбандық үстелдері мен қазандар табылған. Олардың ғұрыптық мақсатта пайдаланылғаны туралы пікір — ғалымдардың негізделген болжамы, өйткені бұл бұйымдар туралы жазба түсініктеме жоқ.', 'В Жетысу найдены бронзовые жертвенные столы и котлы с фигурами животных (барсов, архаров и др.). Мнение, что их использовали в обрядах, — обоснованная догадка учёных, потому что письменных пояснений к этим вещам нет.'),
  (3, 'saka_hats', 'Парсы патшасы І Дарийдің Бехистун жазбасында (б.з.б. VI ғ.) «сака тиграхауда» — «үшкір бөрікті сақтар» аталады; рельефте бұл тайпаның өкілі биік үшкір бөрікпен бейнеленген. Парсы деректерінде «сака хаумаварга» деген топ та кездеседі.', 'В Бехистунской надписи персидского царя Дария I (VI в. до н. э.) названы «сака тиграхауда» — «саки в остроконечных шапках»; на рельефе представитель этого племени изображён в высокой остроконечной шапке. В персидских источниках встречается и группа «сака хаумаварга».'),
  (4, 'hun_script', 'Ғұндар (хунну) туралы негізгі жазба деректер — қытай тарихшыларының еңбектері: Сыма Цяньның «Тарихи жазбалары» мен Бань Гудың «Ханьшуы». Сыма Цянь ғұндарда жазу болмағанын, келісім ауызша жасалғанын жазады; сонымен бірге қытай деректерінде тәңірқұттардың хат алмасуы да сипатталады. Бір автордың сипаттамасы жазудың ешбір түрі болмағанын дәлелдемейді. Бұл деректер сырттан, көбіне қарсылас жақтан жазылғандықтан, оларды сынмен оқу керек.', 'Основные письменные источники о гуннах (хунну) — труды китайских историков: «Исторические записки» Сыма Цяня и «Ханьшу» Бань Гу. Сыма Цянь пишет, что у хунну не было письма и договоры заключались устно; в то же время китайские источники описывают и переписку шаньюев. Описание одного автора не доказывает отсутствие любой письменности. Поскольку эти источники написаны со стороны, чаще всего противником, их нужно читать критически.'),
  (4, 'hun_decimal', 'Сыма Цяньның жазуынша, Мөде (Маодунь) тәңірқұт (б.з.б. 209–174 жж.) тұсында ғұн державасында «он мың атты» басқаратын 24 жоғары басшы болған, олардың әрқайсысының қол астында мыңбасылар, жүзбасылар мен онбасылар тұрған. Бұл ондық жүйе кейін Еуразия даласының көптеген мемлекеттерінде қолданылды.', 'По записям Сыма Цяня, при Модэ (Маодуне)-шаньюе (209–174 гг. до н. э.) в державе хунну было 24 высших начальника над «десятью тысячами всадников», у каждого в подчинении тысячники, сотники и десятники. Эта десятичная система позже применялась во многих государствах Великой степи.'),
  (4, 'hun_three', 'Қытай деректерінде үйсіндер (усунь) Жетісу мен Іле алқабындағы, қаңлылар (кангюй) Сырдарияның орта ағысы мен оған іргелес жерлердегі бөлек мемлекеттер ретінде сипатталады. Ғұн (хунну) державасының орталығы қазіргі Моңғолия жерінде болған. Б.з.б. I ғасырда ғұндар бөлінген соң, Шөже (Чжичжи) тәңірқұт батысқа кетіп, қаңлылармен одақтасып, үйсіндерге қарсы соғысқан.', 'В китайских источниках усуни (усунь) описаны как отдельное государство в Жетысу и долине Или, канглы (кангюй) — на среднем течении Сырдарьи и прилегающих землях. Центр державы хунну находился на территории нынешней Монголии. В I веке до н. э., после раскола хунну, шаньюй Чжичжи ушёл на запад, вступил в союз с канглы и воевал против усуней.'),
  (4, 'hun_final', 'Ғұндар (хунну), үйсіндер мен қаңлылар — деректерде бөлек саяси бірлестіктер ретінде сипатталады. 2025 жылғы геномдық зерттеу Еуропадағы ғұн дәуірінің кейбір адамдары мен хунну ақсүйектерінің арасында генеалогиялық байланыс тапты. Зерттелген қауымдар генетикалық жағынан әркелкі болған. Жекелеген әулеттердің байланысы барлық халықтың, тілдің немесе мемлекеттің бірдей болғанын дәлелдемейді: деректің нақты ауқымын сақтап жазу керек.', 'Гунны (хунну), усуни и канглы описаны в источниках как отдельные политические объединения. Геномное исследование 2025 года нашло генеалогическую связь между некоторыми людьми гуннской эпохи в Европе и знатью хунну. Изученные общины были генетически неоднородны. Связь отдельных родов не доказывает единство всего народа, языка или государства: нужно записывать точный масштаб факта.'),
  (4, 'hun_whistle', 'Ысқырық жебе ұштары (сүйектен жасалған, тесігі бар) хунну дәуірінің ескерткіштерінен табылған — бұл археологиялық дерек. Ал Мөденің өз жауынгерлерін ысқырық жебе арқылы сынап, билікке келгені туралы әйгілі әңгімені Сыма Цянь оқиғадан шамамен бір ғасыр кейін жазған; ол — тарихи баян, оның бөлшектерін тәуелсіз тексеру мүмкін емес.', 'Наконечники свистящих стрел (из кости, с отверстием) найдены на памятниках эпохи хунну — это археологический факт. А знаменитый рассказ о том, как Модэ проверял воинов свистящей стрелой и пришёл к власти, Сыма Цянь записал примерно через век после событий; это историческое повествование, его детали независимо проверить нельзя.'),
  (4, 'hun_fort', '«Ханьшу» Шөженің (Чжичжидің) бекінісін қаңлылар жеріндегі Дулай өзенімен байланыстырады. Дулайды Таласпен сәйкестендіру — кейінгі тарихи-географиялық түсіндіру. Б.з.б. 36 жылы Хань қолбасшылары Гань Яньшоу мен Чэнь Тан бекіністі алып, Шөже қаза тапқан. Ойын картасы — осы түсіндіруге сүйенген көркем реконструкция, нақты қазба орнының көшірмесі емес.', '«Ханьшу» связывает крепость Чжичжи с рекой Дулай на землях канглы. Отождествление Дулая с Таласом — более позднее историко-географическое толкование. В 36 году до н. э. ханьские полководцы Гань Яньшоу и Чэнь Тан взяли крепость, Чжичжи погиб. Карта игры — художественная реконструкция на основе этого толкования, а не копия реального места раскопок.'),
  (4, 'hun_silk', 'Солтүстік Моңғолиядағы Ноин-Ула қорғандарынан (хунну ақсүйектерінің жерлеу орны) қытай жібегі, лак бұйымдары, киіз кілемдер табылған. Бұл ғұндардың Хань империясымен сауда, сый-тарту және «бейбіт туыстық» келісімдері арқылы байланыста болғанын көрсетеді.', 'В курганах Ноин-Ула в Северной Монголии (места погребения знати хунну) найдены китайский шёлк, лаковые изделия, войлочные ковры. Это показывает, что гунны были связаны с империей Хань торговлей, дарами и договорами «мира и родства».'),
  (4, 'hun_zhangqian', 'Хань елшісі Чжан Цянь б.з.б. II ғасырдың екінші жартысында батыс елдеріне екі рет сапар шегіп, Давань, Қаңлы (Кангюй), Үйсін туралы мәлімет жинаған. Оның есебі Сыма Цяньның «Тарихи жазбаларына» (123-тарау) енген және бұл елдер туралы алғашқы толық жазба дерек болып саналады.', 'Ханьский посол Чжан Цянь во второй половине II века до н. э. дважды ездил в западные страны и собрал сведения о Давани, Канглы (Кангюе), Усуни. Его отчёт вошёл в «Исторические записки» Сыма Цяня (гл. 123) и считается первым подробным письменным источником об этих странах.'),
  (5, 'turk_runes', 'Көне түркі руна жазуы (Орхон-Енисей жазуы) — VIII ғасырдағы түркілердің өз жазуы. Ең атақты ескерткіштер Моңғолиядағы Орхон өзені бойында: Күлтегінге (732 ж.) және Білге қағанға (735 ж.) арналған құлпытастар, сондай-ақ Тоңұқұқ ескерткіші. Жазуды 1893 жылы дат тілтанушысы Вильгельм Томсен оқып шықты, кейін В. Радлов мәтіндерді аударды.', 'Древнетюркское рунное письмо (орхоно-енисейское) — собственное письмо тюрков VIII века. Самые известные памятники стоят на реке Орхон в Монголии: стелы в честь Кюль-тегина (732) и Бильге-кагана (735), а также памятник Тоньюкуку. Письмо в 1893 году прочёл датский языковед Вильгельм Томсен, позже тексты перевёл В. Радлов.'),
  (5, 'turk_bolchu', '711 жылы Қапаған қаған тұсында көк түрік әскері Тоңұқұқтың басшылығымен Алтайды асып, Болчу деген жерде түргеш қағанын жеңді — бұл Тоңұқұқ ескерткішінде баяндалады; Күлтегін жазуында да түргештермен шайқас айтылады. Болчудың нақты орны туралы ғалымдардың пікірі әртүрлі (көбіне Жоңғариядағы Ұрұңгу өзені маңы деп есептеледі). Бұл — жеңген жақтың жазуы, сондықтан оны басқа деректермен салыстырған жөн.', 'В 711 году при Капаган-кагане войско кёк-тюрков во главе с Тоньюкуком перешло Алтай и разбило тюргешского кагана в местности Болчу — об этом рассказывает памятник Тоньюкуку; битва с тюргешами упоминается и в надписи Кюль-тегина. О точном месте Болчу мнения учёных расходятся (чаще считают, что это у реки Урунгу в Джунгарии). Это надпись стороны-победителя, поэтому её стоит сверять с другими источниками.'),
  (5, 'turk_balbal', 'Көне түркі ескерткіш кешендерінде марқұмның құлпытасынан шығысқа қарай тізілген тастар — балбалдар — жиі кездеседі. Күлтегін ескерткішіндегі жазуда жеңілген жау басшысы (Баз қаған) балбал етіп қойылғаны айтылады, сондықтан балбалдарды көбіне марқұм тірі кезінде жеңген жаулармен байланыстырады. Алайда әр балбалдың нақты мағынасы мен «бетті» тас мүсіндердің айырмашылығы туралы зерттеушілердің пікірі әртүрлі.', 'В древнетюркских погребальных комплексах часто встречаются камни-балбалы, выстроенные к востоку от стелы покойного. В надписи на памятнике Кюль-тегину сказано, что вождь побеждённых врагов (Баз-каган) поставлен балбалом, поэтому балбалы обычно связывают с врагами, побеждёнными покойным при жизни. Однако о точном смысле каждого балбала и об отличии «лицевых» каменных изваяний мнения исследователей расходятся.'),
  (5, 'turk_final', 'Орхон ескерткіштері — түркі тарихының ең құнды деректері, бірақ олар билеуші әулеттің атынан, оның мақсатына сай жазылған: жеңістер мен қағанның еңбегі алдыңғы орында. Тарихшы мұндай деректі жоққа шығармайды да, сөзсіз қабылдамайды да: автордың кім екенін, кімге арналғанын және не үшін жазылғанын ескеріп, оны қытай жылнамаларымен (мысалы, «Таншу»), археологиялық деректермен және басқа халықтардың мәліметімен салыстырады.', 'Орхонские памятники — ценнейшие источники по тюркской истории, но они написаны от имени правящей династии и в её целях: на первом месте победы и заслуги кагана. Историк не отвергает такой источник, но и не принимает его без вопросов: учитывает, кто автор, кому и зачем написано, и сравнивает его с китайскими летописями (например, «Таншу»), археологическими данными и сведениями других народов.'),
  (5, 'turk_tamga', 'Күлтегін мен Білге қаған құлпытастарының жоғарғы бөлігінде билеуші Ашина әулетінің тау ешкі тәрізді тамғасы бейнеленген. Тамға — рудың, әулеттің меншік және тек белгісі; ол малға, ыдысқа, тасқа салынған.', 'В верхней части стел Кюль-тегина и Бильге-кагана изображена тамга правящей династии Ашина в виде горного козла. Тамга — знак собственности и происхождения рода, династии; её ставили на скот, посуду, камень.'),
  (5, 'turk_kultegin', 'Күлтегін 731 жылы қайтыс болды, ал 732 жылы оның құрметіне Орхон бойында ескерткіш кешені тұрғызылды. Құлпытастың бір бетінде Тан императоры Сюаньцзунның атынан жазылған қытай мәтіні, басқа беттерінде көне түркі руна жазуы бар.', 'Кюль-тегин умер в 731 году, а в 732 году в его честь на Орхоне был воздвигнут погребальный комплекс. На одной стороне стелы — китайский текст от имени танского императора Сюаньцзуна, на других — древнетюркские руны.'),
  (5, 'turk_wolf', 'Қытай жылнамаларында (мысалы, «Чжоушу») Ашина әулетінің арғы анасы қаншық бөрі болғаны туралы аңыз сақталған. Сондықтан түркі қағандарының туларында бөрі басы бейнеленген. Аңыз тарихи оқиға емес, бірақ халықтың өз шығу тегін қалай түсінгені туралы маңызды дерек.', 'В китайских летописях (например, «Чжоушу») сохранилась легенда о том, что праматерью династии Ашина была волчица. Поэтому на знамёнах тюркских каганов изображали голову волка. Легенда — не историческое событие, но важный источник о том, как народ понимал своё происхождение.'),
  (5, 'turk_talas', 'Талас алқабынан (қазіргі Қырғызстан мен Қазақстан шекарасы маңы) тасқа қашалған көне түркі руна жазулары, сондай-ақ руна жазуы бар ағаш таяқша табылған. Бұл руна жазуының тек Орхонда емес, Жетісу мен Талас өңірінде де қолданылғанын көрсетеді.', 'В Таласской долине (у нынешней границы Кыргызстана и Казахстана) найдены высеченные на камне древнетюркские рунические надписи, а также деревянная палочка с рунами. Это показывает, что рунами пользовались не только на Орхоне, но и в Жетысу и Таласе.'),
  (6, 'horde_ulus', 'Шыңғыс хан жерлерін ұлдарына ұлыс етіп бөлді. Үлкен ұлы Жошының ұлысы кейін «Алтын Орда» деп аталды. Жошының ұлы Бату 1236–1242 жылдардағы батыс жорығынан кейін мемлекетті нығайтып, Еділ бойындағы Сарайды астана етті.', 'Чингисхан разделил земли между сыновьями на улусы. Улус старшего сына Джучи позже назвали «Золотой Ордой». Сын Джучи Бату после западного похода 1236–1242 гг. укрепил государство и сделал столицей Сарай на Волге.'),
  (6, 'horde_yam', 'Моңғол империясы мен Алтын Ордада ям — бекеттер жүйесі болды: шабармандар бекетте ат ауыстырып, жарлық пен хабарды алыс жерлерге тез жеткізген. Ресми өкілдер металл тақта — пайза ұстаған.', 'В Монгольской империи и Золотой Орде ям был системой станций: гонцы меняли там коней и быстро доставляли ярлыки и вести в далёкие края. Официальные лица имели металлическую пластину — пайцзу.'),
  (6, 'horde_trade', 'Сарайшық Жайық бойындағы Алтын Орда қаласы болды. Ол Еділ бойын (Сарай) Хорезммен (Үргеніш) байланыстырған сауда жолында тұрды, қолөнер мен теңге соғу дамыды. Марокколық саяхатшы Ибн Баттута 1334 жылы осы қала арқылы Хорезмге өтті. 1395 жылы қаланы Әмір Темір қиратты.', 'Сарайчик был золотоордынским городом на Яике. Он стоял на торговом пути, связывавшем Поволжье (Сарай) с Хорезмом (Ургенч), там развивались ремёсла и чеканка монеты. Марокканский путешественник Ибн Баттута в 1334 году проехал через этот город в Хорезм. В 1395 году город разорил Тимур.'),
  (6, 'horde_sources', 'Алтын Ордада хан болу құқығы Шыңғыс әулетінен шығуға байланысты болды, сондықтан шежірелер саяси маңызға ие еді. Тарихшы шежірені жоққа шығармайды, бірақ сөзсіз де қабылдамайды: оны Рашид ад-Диннің еңбегімен, «Муизз ал-ансаб» сияқты шежірелермен, хандардың атымен соғылған теңгелермен және жылнамалармен салыстырады.', 'В Золотой Орде право стать ханом зависело от происхождения от Чингисидов, поэтому родословные имели политическое значение. Историк не отвергает родословную, но и не принимает её без вопросов: сравнивает её с трудом Рашид ад-Дина, с родословными вроде «Муизз ал-ансаб», с монетами, чеканенными от имени ханов, и с летописями.'),
  (6, 'horde_islam', 'Өзбек хан (1313–1341) тұсында ислам Алтын Ордада мемлекеттік дінге айналды. Дәстүр бойынша Өзбек хан Сарайшықта жерленген деп айтылады, бірақ бұл нақты дәлелденбеген.', 'При Узбек-хане (1313–1341) ислам стал государственной религией Золотой Орды. По преданию, Узбек-хан похоронен в Сарайчике, но это достоверно не доказано.'),
  (6, 'horde_urus', 'XV ғасырда Қазақ хандығының негізін қалаған Керей мен Жәнібек хандар Жошы әулетінен шыққан Орыс ханның ұрпақтары болды.', 'Основатели Казахского ханства в XV веке ханы Керей и Жанибек были потомками Урус-хана из рода Джучи.'),
  (6, 'horde_army', 'Моңғол әскері, оның ішінде Алтын Орда әскері, ондық жүйемен ұйымдасты: ондық, жүздік, мыңдық және түмен. Жеңіл атты садақшылар мен ауыр қаруланған найзагерлер бірлесе әрекет етті.', 'Монгольское войско, в том числе войско Золотой Орды, было устроено по десятичной системе: десяток, сотня, тысяча и тумен. Лёгкие конные лучники и тяжеловооружённые копейщики действовали вместе.'),
  (6, 'horde_paiza', 'Пайза — Моңғол империясы мен Алтын Ордада хан атынан берілген металл (алтын, күміс, қола немесе темір) тақта. Оны ұстаған адам ресми өкілдікке ие болды және ям бекеттерінен ат пен көмек ала алды.', 'Пайцза — металлическая (золотая, серебряная, бронзовая или железная) пластина, выдаваемая от имени хана в Монгольской империи и Золотой Орде. Её держатель имел официальные полномочия и мог получать коней и помощь на ямских станциях.'),
  (6, 'horde_karakhan', 'Қарахан мемлекеті X ғасырдың ортасында Жетісу мен Шығыс Түркістанда құрылды; оқулықтарда оның басы 940 не 942 жылмен байланыстырылады. Астаналары Баласағұн мен Қашқар болды. Сатұқ Бұғра хан исламды қабылдаған алғашқы түрік билеушілерінің бірі еді, ал 960 жылы ислам мемлекеттің ресми дініне айналды. Бұл дәуірде Жүсіп Баласағұнидің «Құтадғу білік» және Махмұд Қашқаридің «Диуани лұғат ат-түрк» еңбектері жазылды.', 'Караханидское государство возникло в середине X века в Жетысу и Восточном Туркестане; в учебниках его начало связывают с 940 или 942 годом. Столицами были Баласагун и Кашгар. Сатук Богра-хан одним из первых тюркских правителей принял ислам, а в 960 году ислам стал официальной религией государства. В эту эпоху были написаны «Кутадгу билиг» Юсуфа Баласагуни и «Диван лугат ат-турк» Махмуда Кашгари.'),
  (6, 'horde_books', '«Құтадғу білік» («Бақытқа бастайтын білім») дастанын Жүсіп Баласағұни 1069–1070 жылдары Қашқарда жазып, Қарахан билеушісіне тартқан; онда әділ билік, білім мен адамгершілік туралы айтылады. Махмұд Қашқари «Диуани лұғат ат-түрк» («Түркі сөздерінің жинағы») сөздігін XI ғасырдың 70-жылдарында Бағдатта жазды (көбіне 1072–1074 жж. деп көрсетіледі): онда түркі сөздері араб тілінде түсіндіріліп, мақал-мәтелдер мен түркі жұрттарының картасы берілген.', 'Поэму «Кутадгу билиг» («Знание, ведущее к счастью») Юсуф Баласагуни написал в 1069–1070 годах в Кашгаре и преподнёс караханидскому правителю; в ней говорится о справедливой власти, знании и нравственности. Махмуд Кашгари составил словарь «Диван лугат ат-турк» («Собрание тюркских слов») в 1070-е годы в Багдаде (чаще всего указывают 1072–1074 гг.): тюркские слова в нём объяснены по-арабски, приведены пословицы и карта тюркских народов.'),
  (6, 'horde_kipchak', 'XI ғасырда Ертіс бойынан батысқа жылжыған қыпшақтар Ертістен Дунайға дейінгі ұланғайыр даланы иеленді. Сол кезден бастап парсы деректерінде (алғаш Насир Хосровта) бұл өлке «Дешті Қыпшақ» — «Қыпшақ даласы» деп аталды; орыс жылнамалары қыпшақтарды «половецтер», византиялықтар «кумандар» деп жазды. XIV ғасырдағы араб тарихшысы әл-Омари Алтын Ордадағы моңғолдардың қыпшақтармен араласып, бір тектен шыққандай болып кеткенін айтады.', 'В XI веке кипчаки, продвинувшиеся с Иртыша на запад, заняли огромную степь от Иртыша до Дуная. С тех пор в персидских источниках (впервые у Насира Хосрова) этот край назывался «Дешт-и Кипчак» — «Кипчакская степь»; русские летописи называли кипчаков «половцами», византийцы — «куманами». Арабский историк XIV века аль-Умари писал, что монголы в Золотой Орде смешались с кипчаками и стали словно одного с ними рода.'),
  (6, 'horde_otrar', '1218 жылы Шыңғыс хан Хорезмге сауда керуенін жіберді. Отырар әкімі Іналшық (Қайырхан) көпестерді тыңшы деп айыптап, қырдырды, тауарын тартып алды; кейін Хорезмшах Мұхаммед Шыңғыс ханның елшісін де өлтіртті. Бұл моңғолдардың Орта Азияға жорығына сылтау болды. 1219 жылдың күзінде моңғолдар Отырарды қоршады; қала шамамен бес ай қорғанып, 1220 жылдың басында алынды, ішкі қамал тағы бір айдай шайқасты. Қайырхан тұтқынға түсіп, өлтірілді.', 'В 1218 году Чингисхан отправил в Хорезм торговый караван. Наместник Отрара Иналчук (Кайыр-хан) обвинил купцов в шпионаже, велел их перебить и забрал товары; затем хорезмшах Мухаммед казнил и посла Чингисхана. Это стало поводом к походу монголов в Среднюю Азию. Осенью 1219 года монголы осадили Отрар; город оборонялся около пяти месяцев и пал в начале 1220 года, цитадель держалась ещё около месяца. Кайыр-хан попал в плен и был казнён.'),
  (6, 'horde_khans', 'Алтын Орда хандары: Бату (1227–1255), оның інісі Берке (1257–1266), Өзбек (1313–1341) және оның ұлы Жәнібек (1342–1357). Ойындағы уақыт — Жәнібек ханның тұсы, шамамен 1350 жыл.', 'Ханы Золотой Орды: Бату (1227–1255), его брат Берке (1257–1266), Узбек (1313–1341) и его сын Джанибек (1342–1357). Время в игре — правление Джанибек-хана, около 1350 года.'),
  (6, 'horde_map', 'Сарайшық — Жайық (Орал) өзенінің төменгі ағысындағы Алтын Орда қаласы. Ол Еділ бойындағы Сарай мен Хорезмді (Үргеніш) байланыстырған сауда жолында тұрды. Қаланың орны қазіргі Атырау облысында.', 'Сарайчик — золотоордынский город в низовьях реки Жайык (Урал). Он стоял на торговом пути, связывавшем Сарай на Итиле с Хорезмом (Ургенч). Его городище находится в нынешней Атырауской области.'),
  (7, 'kaz_zheti', 'Қазақтарда әр адам жеті атасын білуге тиіс болды. Жеті атаға дейінгі туыстар арасында неке тыйым салынған (экзогамия). Шежіре ауызша (жыр) және жазба түрде сақталып, рулар мен аталардың байланысын көрсетті.', 'У казахов каждый должен был знать семь предков. Браки между родственниками до седьмого колена запрещались (экзогамия). Шежире хранилось устно (в песне) и письменно и показывало связи родов и ветвей.'),
  (7, 'kaz_aktaban', '1723 жылы жоңғарлар қазақ жеріне кенеттен басып кірді. Халық жаппай үдере көшіп, көп адам қырылды. Бұл кезең «Ақтабан шұбырынды, Алқакөл сұлама» деп аталады; «Елім-ай» әні осы қасіретпен байланыстырылады.', 'В 1723 году джунгары внезапно вторглись в казахские земли. Народ массово бежал, многие погибли. Это время называют «Актабан шубырынды, Алкаколь сулама»; с этой трагедией связывают песню «Елім-ай».'),
  (7, 'kaz_jarghy', '«Жеті жарғы» — Тәуке хан (XVII ғ. соңы – XVIII ғ. басы) тұсында қалыптасқан әдет-ғұрып құқығының жинағы. Онда жер, отбасы, құн, ант және басқа мәселелер реттелді. Дауларды билер шешкен; Төле би, Қазыбек би, Әйтеке би есімдері ел жадында сақталды.', '«Жеті жарғы» — свод обычного права, сложившийся при Тауке-хане (конец XVII — начало XVIII в.). В нём регулировались земля, семья, кун (выкуп), клятва и другие вопросы. Споры решали бии; в памяти народа остались имена Толе би, Казыбек би и Айтеке би.'),
  (7, 'kaz_bulanty', 'Бұланты шайқасы (көбіне 1728 ж.) — үш жүздің біріккен жасағының жоңғарларды жеңген шайқасы; жер «Қалмақ қырылған» деп аталды. 1729/1730 жылы Аңырақай шайқасы болды. Деректерде жылдар әртүрлі, сондықтан тарихшы ауызша және жазба деректерді салыстырып, айырмашылықты ашық көрсетеді.', 'Битва при Буланты (чаще 1728 г.) — победа объединённого ополчения трёх жузов над джунгарами; место назвали «Калмак кырылган». В 1729/1730 году произошла Анракайская битва. В источниках годы расходятся, поэтому историк сверяет устные и письменные источники и открыто показывает расхождения.'),
  (7, 'kaz_turt', 'Төрт түлік — жылқы, түйе, сиыр және қой-ешкі. Көшпелі қазақтар маусымға қарай көктеу, жайлау, күзеу және қыстауға көшіп отырды.', '«Төрт түлік» — четыре вида скота: лошади, верблюды, коровы и овцы с козами. Кочевые казахи по сезонам перекочёвывали на весенние, летние, осенние и зимние пастбища.'),
  (7, 'kaz_kiiz', 'Шаңырақ — киіз үйдің төбесіндегі дөңгелек күмбез. Ол отбасының, әулеттің белгісі саналып, әке шаңырағы кенже ұлға қалған.', 'Шанырак — круглый купол наверху юрты. Он считается знаком семьи, рода; отцовский шанырак оставался младшему сыну.'),
  (7, 'kaz_zhuz', 'Қазақтар Ұлы жүз, Орта жүз және Кіші жүз болып бөлінді. Жоңғарларға қарсы күресте үш жүздің жасақтары бірікті.', 'Казахи делились на Старший (Ұлы), Средний (Орта) и Младший (Кіші) жуз. В борьбе с джунгарами ополчения трёх жузов объединились.'),
  (7, 'kaz_turkistan', 'XVII–XVIII ғасырларда Түркістан Қазақ хандығының саяси орталығы болды. Мұнда Қожа Ахмет Ясауи кесенесі тұр; оның маңында көптеген қазақ хандары мен билері жерленген.', 'В XVII–XVIII веках Туркестан был политическим центром Казахского ханства. Здесь стоит мавзолей Ходжи Ахмеда Ясави; рядом с ним похоронены многие казахские ханы и бии.'),
  (7, 'kaz_gap', 'Жошы әулетінен шыққан Керей мен Жәнібек сұлтандар Әбілқайыр хандығынан бөлініп, Шу мен Талас бойына көшіп келді; Қазақ хандығы осылай құрылды. Құрылған жылы деректерде әртүрлі көрсетіледі (көбіне 1465 жыл). Есім, Тәуке және Абылай — кейінгі ғасырлардағы хандар.', 'Султаны Керей и Жанибек из рода Джучи отделились от ханства Абулхаира и откочевали в долины Чу и Таласа; так возникло Казахское ханство. Год его основания в источниках указывают по-разному (чаще всего 1465 год). Есим, Тауке и Абылай — ханы более поздних веков.'),
  (8, 'rus_1822', '1822 жылғы «Сібір қырғыздары туралы жарғы» бойынша Орта жүзде хан билігі жойылып, округтар (приказдар) құрылды. Округтарды аға сұлтандар басқарды. Ақмола округтық приказы 1830 жылы ашылды.', 'По «Уставу о сибирских киргизах» 1822 года в Среднем жузе упразднили ханскую власть и создали округа (приказы). Округами управляли ага-султаны. Акмолинский окружной приказ открыт в 1830 году.'),
  (8, 'rus_fort', 'Бекіністер мен округтардың құрылуы жер пайдалануды өзгертті: жайылымдар мен қыстаулар тарылды, көш жолдары өзгерді. Бір бөлігі егіншілікке, отырықшылыққа көше бастады. Сонымен бірге айырбас сауда, кейін мектептер пайда болды. Өзгерістің бағасы әртүрлі адамдар үшін әртүрлі болды.', 'Создание крепостей и округов изменило землепользование: пастбища и зимовки сократились, пути кочёвок изменились. Часть людей начала переходить к земледелию и оседлости. Вместе с тем появились меновая торговля, а позже школы. Цена перемен для разных людей была разной.'),
  (8, 'rus_kenesary', 'Кенесары Қасымұлы (1802–1847) 1837–1847 жылдары хан билігін қалпына келтіру және қазақ жерлерін қорғау үшін ұлт-азаттық көтеріліс бастады. 1838 жылы оның жасағы Ақмола бекінісін өртеді. 1841 жылы ол хан болып жарияланды.', 'Кенесары Касымулы (1802–1847) в 1837–1847 годах возглавил национально-освободительное восстание за восстановление ханской власти и защиту казахских земель. В 1838 году его отряды сожгли Акмолинское укрепление. В 1841 году он был провозглашён ханом.'),
  (8, 'rus_sources', 'Ресми есептер (приказ құжаттары, әскери рапорттар) мен ауызша тарих бір оқиғаны әртүрлі көрсетуі мүмкін. Тарихшы әр дереккөздің авторын, мақсатын, жазылған уақытын анықтап, оларды өзара салыстырады және айырмашылықтың себебін түсіндіреді.', 'Официальные отчёты (документы приказа, военные рапорты) и устная история могут показывать одно событие по-разному. Историк выясняет автора, цель и время создания каждого источника, сравнивает их между собой и объясняет причину расхождений.'),
  (8, 'rus_isatay', '1836–1838 жылдары Бөкей ордасында Исатай Тайманұлы мен Махамбет Өтемісұлы бастаған көтеріліс болды. Махамбеттің жалынды өлеңдері қазақ поэзиясының асыл мұрасы.', 'В 1836–1838 годах в Букеевской орде произошло восстание под руководством Исатая Тайманулы и Махамбета Утемисулы. Пламенные стихи Махамбета — драгоценное наследие казахской поэзии.'),
  (8, 'rus_trade', 'XIX ғасырда бекіністер мен шекара маңындағы айырбас аулаларында және жәрмеңкелерде мал мен мал өнімдері мата, шәй, темір бұйымдар сияқты тауарларға айырбасталды. Саудада татар көпестері маңызды рөл атқарды.', 'В XIX веке на меновых дворах у крепостей и границы и на ярмарках скот и продукты скотоводства обменивали на ткани, чай, железные изделия. Важную роль в торговле играли татарские купцы.'),
  (8, 'rus_school', 'Ыбырай Алтынсарин (1841–1889) — қазақ ағартушысы, педагог. 1864 жылы Торғайда қазақ балаларына арналған мектеп ашты, 1879 жылы «Қырғыз хрестоматиясын» жазды.', 'Ибрай Алтынсарин (1841–1889) — казахский просветитель и педагог. В 1864 году в Тургае открыл школу для казахских детей, в 1879 году написал «Киргизскую хрестоматию».'),
  (8, 'rus_aul', 'XIX ғасырда мал шаруашылығымен қатар егіншілік кеңейді; ауылдардың бір бөлігі қыстауларда тұрақтап, жартылай отырықшы өмірге бейімделді.', 'В XIX веке наряду со скотоводством расширялось земледелие; часть аулов закреплялась на зимовках и привыкала к полуоседлой жизни.'),
  (8, 'rus_1916', '1916 жылғы 25 маусымда II Николай Түркістан мен Дала өлкесінің 19 бен 43 жас аралығындағы «бұратана» ер адамдарын майдан маңында қорғаныс құрылыстарын салуға және тыл жұмыстарына алу туралы жарлыққа қол қойды. Егін мен шөп науқанының қызған шағында шыққан жарлық жердің тартып алынуы мен салық ауыртпалығынан жиналған наразылықты өршітіп, 1916 жылғы ұлт-азаттық көтерілістің тікелей себебі болды.', '25 июня 1916 года Николай II подписал указ о привлечении «инородческого» мужского населения Туркестана и Степного края в возрасте от 19 до 43 лет к работам по устройству оборонительных сооружений и тыловым работам в районе действующей армии. Указ, вышедший в разгар страды и сенокоса, обострил недовольство, накопившееся из-за изъятия земель и тяжёлых налогов, и стал непосредственной причиной национально-освободительного восстания 1916 года.'),
  (8, 'rus_torgai', 'Торғай даласы 1916 жылғы көтерілістің ең ұйымдасқан әрі ұзаққа созылған ошақтарының бірі болды. Көтерілісшілер Әбдіғапар Жанбосынұлын хан, Амангелді Имановты сардарбек (бас қолбасшы) етіп сайлады. 1916 жылдың күзінде олар Торғай қаласын қоршады; қарулы күрес 1917 жылдың басына дейін жалғасты. Кенесары, Исатай және Сырым — XVIII–XIX ғасырлардағы көтерілістердің басшылары.', 'Тургайская степь стала одним из самых организованных и долгих очагов восстания 1916 года. Повстанцы избрали ханом Абдигаппара Жанбосынова, а сардарбеком (главнокомандующим) — Амангельды Иманова. Осенью 1916 года они осадили город Тургай; вооружённая борьба продолжалась до начала 1917 года. Кенесары, Исатай и Сырым — предводители восстаний XVIII–XIX веков.'),
  (8, 'rus_alash', '1913–1918 жылдары Ахмет Байтұрсынұлы басқарған «Қазақ» газеті Әлихан Бөкейхан мен Міржақып Дулатұлының қатысуымен шығып, қазақ зиялыларын біріктірді. 1917 жылы Алаш партиясы құрылды. 1917 жылғы 5–13 желтоқсанда Орынборда өткен II жалпықазақ съезі Алаш автономиясын жариялап, оның үкіметі — Алашорданы құрды; төрағасы болып Әлихан Бөкейхан сайланды. Алашорда 1920 жылы таратылды.', 'В 1913–1918 годах газета «Казах» под руководством Ахмета Байтурсынулы выходила при участии Алихана Букейхана и Миржакыпа Дулатулы и объединяла казахскую интеллигенцию. В 1917 году была создана партия Алаш. II Всеказахский съезд, прошедший 5–13 декабря 1917 года в Оренбурге, провозгласил автономию Алаш и создал её правительство — Алаш-Орду; председателем избрали Алихана Букейхана. Алаш-Орда была упразднена в 1920 году.'),
  (8, 'rus_match', 'Исатай Тайманұлы мен Махамбет Өтемісұлы 1836–1838 жылдары Бөкей ордасындағы көтерілісті басқарды. Кенесары Қасымұлы 1837–1847 жылдары хан билігін қалпына келтіру үшін күресті. Ыбырай Алтынсарин 1864 жылы Торғайда қазақ балаларына арналған мектеп ашты. Амангелді Иманов 1916 жылғы Торғай көтерілісінің сардарбегі болды.', 'Исатай Тайманулы и Махамбет Утемисулы в 1836–1838 годах возглавили восстание в Букеевской орде. Кенесары Касымулы в 1837–1847 годах боролся за восстановление ханской власти. Ыбырай Алтынсарин в 1864 году открыл в Тургае школу для казахских детей. Амангельды Иманов был сардарбеком Тургайского восстания 1916 года.'),
  (9, 'sov_316', '316-атқыштар дивизиясы 1941 жылы шілде–тамызда Алма-Атада генерал-майор И. В. Панфиловтың басшылығымен жасақталды. 1941 жылдың күзінде Мәскеу түбінде, Волоколам бағытында шайқасты; кейін 8-гвардиялық дивизия атағын алды.', '316-я стрелковая дивизия сформирована в июле–августе 1941 года в Алма-Ате под руководством генерал-майора И. В. Панфилова. Осенью 1941 года сражалась под Москвой на Волоколамском направлении; позже получила звание 8-й гвардейской.'),
  (9, 'sov_evac', '1941–1942 жылдары Қазақстанға жүздеген өнеркәсіп орны мен жүз мыңдаған адам көшірілді. Республика майданға қару-жарақ, оқ-дәрі, металл, көмір, азық-түлік жіберді. Майданға кеткендердің орнына әйелдер, қарттар мен жасөспірімдер жұмыс істеді.', 'В 1941–1942 годах в Казахстан эвакуировали сотни предприятий и сотни тысяч людей. Республика отправляла фронту оружие, боеприпасы, металл, уголь, продовольствие. Вместо ушедших на фронт работали женщины, старики и подростки.'),
  (9, 'sov_zhambyl', 'Жамбыл Жабаев 1941 жылдың қыркүйегінде «Ленинградтық өренім» өлеңін шығарды. Ол орыс тіліне аударылып, қоршаудағы Ленинградта радиодан оқылды және плакаттарға басылды; қала тұрғындарына рухани қолдау болды.', 'Джамбул Джабаев в сентябре 1941 года создал стихотворение «Ленинградцы, дети мои». Его перевели на русский язык, читали по радио в блокадном Ленинграде и печатали на плакатах; оно стало духовной поддержкой жителям города.'),
  (9, 'sov_memory', 'Соғыс жадын зерттеу үшін тарихшы майдангерлердің хаттарын, ресми құжаттарды (тізімдер, хабарламалар, мұрағат деректері) және отбасылардың естеліктерін салыстырады. Бұл әр адамның тағдырын нақты қалпына келтіруге және аңыз бен фактіні ажыратуға мүмкіндік береді.', 'Чтобы исследовать память о войне, историк сравнивает письма фронтовиков, официальные документы (списки, извещения, архивные данные) и воспоминания семей. Это позволяет точно восстановить судьбу каждого человека и отделить легенду от факта.'),
  (9, 'sov_famine', '1931–1933 жылдардағы аштық (Ашаршылық) күштеп ұжымдастыру, малды тәркілеу және көшпелілерді күштеп отырықшыландыру салдарынан болды. Ол қазақ халқының орасан көп адамын жалмады, көптеген адам республикадан тыс жерлерге көшіп кетті.', 'Голод 1931–1933 годов (Ашаршылық) был вызван насильственной коллективизацией, конфискацией скота и принудительным оседанием кочевников. Он унёс огромное число казахов, многие откочевали за пределы республики.'),
  (9, 'sov_ind', 'Түркістан–Сібір теміржолы (Түрксіб) 1930 жылы іске қосылды. Ол Сібір мен Орта Азияны байланыстырып, индустрияландыруда маңызды рөл атқарды.', 'Туркестано-Сибирская железная дорога (Турксиб) пущена в 1930 году. Она связала Сибирь и Среднюю Азию и сыграла важную роль в индустриализации.'),
  (9, 'sov_heroes', 'Әлия Молдағұлова — мерген, Мәншүк Мәметова — пулеметші. Екеуі де майданда қаза тауып, Кеңес Одағының Батыры атағына ие болды.', 'Алия Молдагулова — снайпер, Маншук Маметова — пулемётчица. Обе погибли на фронте и получили звание Героя Советского Союза.'),
  (9, 'sov_deport', '1930–1940 жылдары КСРО-да бірнеше халық (корейлер, немістер, шешендер, ингуштар және басқалар) Қазақстанға күштеп жер аударылды. Жергілікті тұрғындар қиын жағдайда оларға көмектесті.', 'В 1930–1940-х годах в СССР несколько народов (корейцы, немцы, чеченцы, ингуши и другие) были насильственно депортированы в Казахстан. Местные жители помогали им в тяжёлых условиях.'),
  (9, 'sov_1937', '1937–1938 жылдары КСРО-да жаппай саяси қуғын-сүргін жүрді. Алаш қозғалысының көшбасшылары жалған айыппен «халық жауы» атанды: Әлихан Бөкейхан 1937 жылғы 27 қыркүйекте Мәскеуде, Ахмет Байтұрсынұлы 1937 жылғы 8 желтоқсанда Алматыда атылды, Мағжан Жұмабаев 1938 жылы атылды. Міржақып Дулатұлы бұған дейін, 1935 жылы лагерьде қайтыс болған еді. Олардың кітаптарына ұзақ жыл тыйым салынды; Бөкейхан мен Байтұрсынұлы 1988–1989 жылдары ғана ақталды.', 'В 1937–1938 годах в СССР шли массовые политические репрессии. Лидеров движения Алаш по ложным обвинениям объявили «врагами народа»: Алихан Букейхан был расстрелян 27 сентября 1937 года в Москве, Ахмет Байтурсынулы — 8 декабря 1937 года в Алма-Ате, Магжан Жумабаев — в 1938 году. Миржакып Дулатулы ещё раньше, в 1935 году, умер в лагере. Их книги были надолго запрещены; Букейхана и Байтурсынулы реабилитировали лишь в 1988–1989 годах.'),
  (9, 'sov_alzhir', 'АЛЖИР — «Отанын сатқандардың әйелдерінің Ақмола лагері» (Қарлагтың арнаулы бөлімшесі, «26-нүкте»). 1938 жылдың қаңтарынан бастап оған күйеулері «халық жауы» деп қуғын-сүргінге ұшыраған мыңдаған әйел жіберілді; олар ешқандай қылмыссыз, тек отбасы мүшесі болғаны үшін жазаланды. Жергілікті ауыл тұрғындары тұтқын әйелдерге жасырын тамақ беріп көмектескені туралы естеліктер сақталған. Бүгінде сол жерде саяси қуғын-сүргін құрбандарына арналған «АЛЖИР» мемориалдық-мұражай кешені бар.', 'АЛЖИР — «Акмолинский лагерь жён изменников Родины» (особое отделение Карлага, «26-я точка»). С января 1938 года туда отправляли тысячи женщин, чьих мужей репрессировали как «врагов народа»; их наказали без всякого преступления — только за то, что они члены семьи. Сохранились воспоминания о том, как жители окрестных аулов тайком передавали заключённым еду. Сегодня там мемориально-музейный комплекс «АЛЖИР» памяти жертв политических репрессий.'),
  (9, 'sov_tyn', 'Тың және тыңайған жерлерді игеру туралы шешімді КОКП Орталық Комитетінің 1954 жылғы ақпан–наурыз пленумы қабылдады. Игерудің негізгі бөлігі Солтүстік Қазақстанға тиді: мұнда шамамен 25 миллион гектар жер жыртылып, жүздеген жаңа совхоз құрылды, КСРО-ның түкпір-түкпірінен жүз мыңдаған адам келді. Қазақстан ірі астық өндірушіге айналды, бірақ жайылымдардың тарылуы, топырақ эрозиясы мен шаң дауылдары сияқты ауыр салдарлар да болды.', 'Решение об освоении целинных и залежных земель принял февральско-мартовский пленум ЦК КПСС 1954 года. Основная часть освоения пришлась на Северный Казахстан: здесь распахали около 25 миллионов гектаров, создали сотни новых совхозов, со всех концов СССР приехали сотни тысяч человек. Казахстан стал крупным производителем зерна, но были и тяжёлые последствия: сокращение пастбищ, эрозия почв и пыльные бури.'),
  (9, 'sov_baikonur', 'Байқоңыр ғарыш айлағы 1955 жылы Қызылорда облысындағы Төретам бекетінің маңында салына бастады (ресми құрылған күні — 1955 жылғы 2 маусым). 1957 жылғы 4 қазанда осы жерден Жердің алғашқы жасанды серігі, 1961 жылғы 12 сәуірде Юрий Гагарин мінген «Восток» кемесі ұшырылды. Ғарыш айлағы Қазақстан жерінде орналасқан; 1994 жылдан бері оны Ресей жалға алып отыр.', 'Космодром Байконур начали строить в 1955 году у станции Тюратам в Кзыл-Ординской области (официальный день основания — 2 июня 1955 года). Отсюда 4 октября 1957 года запустили первый искусственный спутник Земли, а 12 апреля 1961 года — корабль «Восток» с Юрием Гагариным. Космодром находится на территории Казахстана; с 1994 года его арендует Россия.'),
  (9, 'sov_order', 'Түрксіб 1930 жылы іске қосылды; Алаш қайраткерлері Ә. Бөкейхан мен А. Байтұрсынұлы 1937 жылы атылды; 316-атқыштар дивизиясы 1941 жылы Алматыда жасақталды; тың игеру 1954 жылы басталды.', 'Турксиб открыт в 1930 году; деятели Алаш А. Букейхан и А. Байтурсынулы расстреляны в 1937 году; 316-я стрелковая дивизия сформирована в Алма-Ате в 1941 году; освоение целины началось в 1954 году.'),
  (10, 'ind_1991', '1991 жылғы 16 желтоқсанда «Қазақстан Республикасының мемлекеттік тәуелсіздігі туралы» Конституциялық заң қабылданды. 16 желтоқсан — Тәуелсіздік күні.', '16 декабря 1991 года принят Конституционный закон «О государственной независимости Республики Казахстан». 16 декабря — День Независимости.'),
  (10, 'ind_symbols', 'Қазақстан Республикасының мемлекеттік Туы мен Елтаңбасы 1992 жылғы 4 маусымда бекітілді. «Менің Қазақстаным» әнұраны 2006 жылдан бері мемлекеттік әнұран.', 'Государственный флаг и герб Республики Казахстан утверждены 4 июня 1992 года. Гимн «Менің Қазақстаным» — государственный гимн с 2006 года.'),
  (10, 'ind_semey', 'Семей ядролық сынақ полигоны 1949–1989 жылдары жұмыс істеді. 1989 жылы «Невада – Семей» қозғалысы құрылды. Полигон 1991 жылғы 29 тамызда жабылды.', 'Семипалатинский ядерный полигон работал в 1949–1989 годах. В 1989 году возникло движение «Невада – Семей». Полигон закрыт 29 августа 1991 года.'),
  (10, 'ind_shezhire', 'Тарихшы бір ғана нұсқаға сүйенбейді. Археологиялық, жазба және ауызша деректерді салыстыра отырып, оларды кім және не үшін жасағанын түсінеді; ұмытылған немесе өшірілген адамдар мен топтардың тарихын да қалпына келтіреді.', 'Историк не опирается на одну версию. Сравнивая археологические, письменные и устные источники, он понимает, кто и зачем их создал; восстанавливает и историю забытых или вычеркнутых людей и групп.'),
  (10, 'ind_zheltoqsan', '1986 жылғы 17–18 желтоқсанда Алматыда жастар алаңға шықты. Бұл оқиға кейін тәуелсіздікке жеткен жолдың маңызды белесі ретінде бағаланады.', '17–18 декабря 1986 года в Алматы молодёжь вышла на площадь. Позже эти события оценивают как важный рубеж на пути к независимости.'),
  (10, 'ind_constitution', 'Қазақстан Республикасының қазіргі Конституциясы 1995 жылғы 30 тамызда республикалық референдумда қабылданды.', 'Действующая Конституция Республики Казахстан принята на республиканском референдуме 30 августа 1995 года.'),
  (10, 'ind_tenge', 'Ұлттық валюта — теңге 1993 жылғы 15 қарашада айналымға енгізілді. «Теңге» сөзі ерте заманнан келеді: Алтын Орда дәуірінде де күміс теңгелер соғылған.', 'Национальная валюта — тенге — введена в обращение 15 ноября 1993 года. Слово «тенге» очень древнее: серебряные тенге чеканили ещё в эпоху Золотой Орды.'),
  (10, 'ind_capital', '1997 жылы Қазақстанның елордасы Алматыдан Ақмолаға көшірілді; 1998 жылы қала Астана деп аталды.', 'В 1997 году столица Казахстана была перенесена из Алматы в Акмолу; в 1998 году город получил название Астана.'),
  (10, 'ind_order', '1986 жылғы 17–18 желтоқсан — Алматыдағы Желтоқсан оқиғасы; 1991 жылғы 16 желтоқсан — тәуелсіздік туралы Конституциялық заң; 1993 жылғы 15 қараша — теңге айналымға енді; 1995 жылғы 30 тамыз — қазіргі Конституция қабылданды; 1997 жыл — елорда Алматыдан Ақмолаға көшті.', '17–18 декабря 1986 года — Желтоксан в Алма-Ате; 16 декабря 1991 года — Конституционный закон о независимости; 15 ноября 1993 года — введён тенге; 30 августа 1995 года — принята действующая Конституция; 1997 год — столица перенесена из Алматы в Акмолу.')
